local HopsGrower = {}
local PRODUCTS = {
    common_hops_bale = { name = "Bala navadnega hmelja", woodCost = 1, ropeCost = 1, time = 4, cost = 35, happiness = 1, food = 5, description = "Bala suhega hmelja za pivovarne." },
    dried_hops_sack = { name = "Vreča sušenega hmelja", woodCost = 1, linenCost = 1, ropeCost = 1, time = 6, cost = 90, happiness = 1, food = 10, prestige = 1, description = "Vreča sušenega hmelja za trgovino." },
    pressed_hops_cake = { name = "Stisnjena pogača hmelja", woodCost = 1, ironCost = 1, linenCost = 1, time = 9, cost = 220, happiness = 2, food = 18, prestige = 4, description = "Stisnjena pogača hmelja za dolgo shranjevanje." },
    silver_tied_hops = { name = "Srebrnopovezan hmelj", woodCost = 2, ironCost = 1, silverCost = 1, linenCost = 1, time = 13, cost = 580, happiness = 3, food = 30, prestige = 12, description = "Hmelj vezan s srebrno nitjo za visoke plemiče." },
    gold_woven_hops_wreath = { name = "Zlato pleteni venec hmelja", woodCost = 2, goldCost = 1, silverCost = 1, linenCost = 2, time = 17, cost = 1300, happiness = 5, food = 45, prestige = 22, description = "Venec hmelja pleten z zlato nitjo za visoko plemstvo." },
    royal_hops_harvest_basket = { name = "Kraljevski koš hmelja", woodCost = 3, goldCost = 2, silverCost = 2, linenCost = 2, jewelCost = 1, pearlCost = 1, time = 24, cost = 3300, happiness = 11, food = 80, prestige = 55, description = "Veliki kraljevski koš hmelja z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    hops_field = { name = "Hmeljevo polje", cost = { gold = 220, wood = 100, stone = 80, rope = 6 }, upkeep = 5, qualityBonus = 5 },
    drying_barn = { name = "Sušilna stodola", cost = { gold = 800, wood = 240, stone = 220, iron = 6 }, upkeep = 18, qualityBonus = 18 },
    brewing_atelier = { name = "Pivovarski atelje", cost = { gold = 2200, wood = 360, stone = 480, silver = 28, iron = 8 }, upkeep = 50, qualityBonus = 30 },
    royal_hops_palace = { name = "Kraljevska hmeljeva palača", cost = { gold = 9200, wood = 580, stone = 720, gold = 55, jewel = 14 }, upkeep = 185, qualityBonus = 55, prestigeBonus = 50 },
}
HopsGrower.woodStock = 16; HopsGrower.ropeStock = 12; HopsGrower.linenStock = 10; HopsGrower.ironStock = 8; HopsGrower.silverStock = 6; HopsGrower.goldStock = 6; HopsGrower.jewelStock = 4; HopsGrower.pearlStock = 4
HopsGrower.productStock = {}; HopsGrower.buildings = {}; HopsGrower.maker = nil; HopsGrower.activeMaking = {}; HopsGrower.totalProducts = 0; HopsGrower.dayTimer = 0
function HopsGrower.init() HopsGrower.woodStock=16; HopsGrower.ropeStock=12; HopsGrower.linenStock=10; HopsGrower.ironStock=8; HopsGrower.silverStock=6; HopsGrower.goldStock=6; HopsGrower.jewelStock=4; HopsGrower.pearlStock=4; HopsGrower.productStock={}; HopsGrower.buildings={}; HopsGrower.maker=nil; HopsGrower.activeMaking={}; HopsGrower.totalProducts=0; HopsGrower.dayTimer=0; print("[HopsGrower] Royal Hops Grower System initialized (6 products, 4 buildings)") end
function HopsGrower.hireMaker(n,s) s=s or math.random(55,90); local c=440+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HopsGrower.maker={name=n or ("Hmeljar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Hmeljar najet: %s (spretnost: %d)",HopsGrower.maker.name,s),"success") end; return true end
function HopsGrower.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HopsGrower.build(id) local ok,e=HopsGrower.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HopsGrower.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HopsGrower.getQualityBonus() local b=0; for _,bd in ipairs(HopsGrower.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HopsGrower.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and HopsGrower.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ropeCost and HopsGrower.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.linenCost and HopsGrower.linenStock<(d.linenCost or 0) then return false,"Premalo lanu" end; if d.ironCost and HopsGrower.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.silverCost and HopsGrower.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HopsGrower.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HopsGrower.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HopsGrower.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HopsGrower.buildings==0 then return false,"Potrebno hmeljevo polje" end; if not HopsGrower.maker then return false,"Potreben hmeljar" end; return true end
function HopsGrower.make(pt,qty) qty=qty or 1; local ok,e=HopsGrower.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then HopsGrower.woodStock=HopsGrower.woodStock-d.woodCost*qty end; if d.ropeCost then HopsGrower.ropeStock=HopsGrower.ropeStock-d.ropeCost*qty end; if d.linenCost then HopsGrower.linenStock=HopsGrower.linenStock-d.linenCost*qty end; if d.ironCost then HopsGrower.ironStock=HopsGrower.ironStock-d.ironCost*qty end; if d.silverCost then HopsGrower.silverStock=HopsGrower.silverStock-d.silverCost*qty end; if d.goldCost then HopsGrower.goldStock=HopsGrower.goldStock-d.goldCost*qty end; if d.jewelCost then HopsGrower.jewelStock=HopsGrower.jewelStock-d.jewelCost*qty end; if d.pearlCost then HopsGrower.pearlStock=HopsGrower.pearlStock-d.pearlCost*qty end; local t=d.time; if HopsGrower.maker then t=math.max(1,t-math.floor(HopsGrower.maker.skill/14)) end; table.insert(HopsGrower.activeMaking,{id="hops_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Setev: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HopsGrower.completeMaking(m) local q=1.0+(HopsGrower.getQualityBonus()/100); if HopsGrower.maker then q=q+(HopsGrower.maker.skill/160) end; q=math.min(2.2,q); HopsGrower.productStock[m.productType]=(HopsGrower.productStock[m.productType] or 0)+m.quantity; HopsGrower.totalProducts=HopsGrower.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HopsGrower.maker then HopsGrower.maker.itemsMade=HopsGrower.maker.itemsMade+m.quantity; if math.random()<0.25 then HopsGrower.maker.skill=math.min(100,HopsGrower.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Hmelj pripravljen: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"hops.harvested",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function HopsGrower.update(dt) if not _G.state then return end; HopsGrower.dayTimer=HopsGrower.dayTimer+dt; if HopsGrower.dayTimer>=30 then HopsGrower.dayTimer=0; for i=#HopsGrower.activeMaking,1,-1 do local m=HopsGrower.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HopsGrower.completeMaking(m); table.remove(HopsGrower.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HopsGrower.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HopsGrower.maker then tu=tu+11 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HopsGrower.getStats() return {woodStock=HopsGrower.woodStock,ropeStock=HopsGrower.ropeStock,linenStock=HopsGrower.linenStock,ironStock=HopsGrower.ironStock,silverStock=HopsGrower.silverStock,goldStock=HopsGrower.goldStock,jewelStock=HopsGrower.jewelStock,pearlStock=HopsGrower.pearlStock,productStock=HopsGrower.productStock,numBuildings=#HopsGrower.buildings,hasMaker=HopsGrower.maker~=nil,makerName=HopsGrower.maker and HopsGrower.maker.name or "—",makerSkill=HopsGrower.maker and HopsGrower.maker.skill or 0,activeMaking=#HopsGrower.activeMaking,totalProducts=HopsGrower.totalProducts} end
return HopsGrower
